public class Main {
    static List<List<Integer>> result = new ArrayList<>();

    public static void backtrack(List<Integer> current, List<Integer> remaining) {

        // BASE CASE - used all numbers
        if (remaining.isEmpty()) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = 0; i < remaining.size(); i++) {

            // CHOOSE
            current.add(remaining.get(i));

            List<Integer> nextRemaining = new ArrayList<>(remaining);
            nextRemaining.remove(i);

            // EXPLORE
            backtrack(current, nextRemaining);

            // UNCHOOSE
            current.remove(current.size() - 1);
        }
    }

    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3));
        backtrack(new ArrayList<>(), nums);

        for (List<Integer> perm : result) {
            System.out.println(perm);
        }
    }
}

