void backtrack(vector<int>& path, const vector<int>& choices,
               vector<vector<int>>& result) {

    // 1. BASE CASE — complete solution found

    if (isComplete(path)) {
        result.push_back(path);   // vector is copied automatically
        return;
    }

    // 2. Try every available choice

    for (int choice : choices) {

        // 3. PRUNE: skip invalid choices
        if (!isValid(choice, path))
            continue;

        // 4. CHOOSE
        path.push_back(choice);

        // 5. EXPLORE
        backtrack(path, nextChoices(choices, choice), result);

        // 6. UNCHOOSE (Backtrack)
        path.pop_back();
    }
}
